starter:
def modern_enough(version):
    """True if version is 3.10 or newer."""
    return version >= "3.10"

solution:
def modern_enough(version):
    """True if version is 3.10 or newer."""
    parts = []
    for part in version.split("."):
        parts.append(int(part))
    return tuple(parts) >= (3, 10)

